def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            safe_bid = DAILY_SALARY * 0.8
        return min(budget, max(0, safe_bid))

    prev_bids = []
    desperate_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > DAILY_SALARY * 4:
            rich_opponents += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))
            if prev.get('status') == 'lost' and opp.get('hp', 10) <= 3:
                desperate_opponents += 1

    total_players = 1 + len(alive_opponents)
    supply_pressure = float(supply) / float(total_players * WATER_REQ)

    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.92
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * 0.72
    else:
        if supply_pressure >= 0.45:
            base = DAILY_SALARY * 0.46
        elif supply_pressure >= 0.35:
            base = DAILY_SALARY * 0.56
        else:
            base = DAILY_SALARY * 0.66

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        target = max(avg_prev + 1.0, highest_prev * 0.9)
        if hp <= 4 or no_water_days >= 1:
            base = max(base, target)
        else:
            base = max(base, min(target, DAILY_SALARY * 0.72))

    if desperate_opponents >= max(1, len(alive_opponents) // 2):
        base += 4
    if rich_opponents >= max(1, len(alive_opponents) // 2):
        base += 3

    if budget < DAILY_SALARY * 2:
        base = min(base, budget * 0.6 + 2)
    elif budget > DAILY_SALARY * 6 and (hp <= 4 or no_water_days >= 1):
        base += 3

    base = max(0, min(base, budget))
    return base

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # Budget guardrails
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    # If we are in danger, bid aggressively regardless of opponent
    if hp <= 2 or no_water_days >= 2:
        return max(0.0, min(budget, DAILY_SALARY * 0.95))

    # Collect opponents that are alive and have a usable previous bid
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                alive_opps.append((opp_id, float(prev.get('bid', 0.0)), prev))

    # Default: moderate bid to avoid overspending
    base_bid = DAILY_SALARY * 0.55

    if alive_opps:
        prev_bids = [b for (_, b, _) in alive_opps]
        highest_prev_bid = max(prev_bids)
        lowest_prev_bid = min(prev_bids)

        # If someone previously signaled high urgency (near our salary), match/beat them
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If we have decent hp, slightly undercut; if not, bid closer to max
            if hp >= 4:
                bid = highest_prev_bid + 2.0
            else:
                bid = highest_prev_bid + 6.0
        else:
            # If pressure was low, bid around base but nudge above the median/low bidder
            # Use highest_prev_bid as a conservative anchor
            bid = max(base_bid, highest_prev_bid + 1.0)

        # Supply-aware adjustment: when supply is tight, increase aggressiveness
        # supply is within [15,25] typically; normalize loosely
        if float(supply) <= 18.0:
            bid *= 1.15
        elif float(supply) >= 22.0:
            bid *= 0.95

        # Ensure bid is feasible
        return max(0.0, min(budget, bid))

    # No opponent trace info: bid moderately
    return max(0.0, min(budget, base_bid))
